let qIndex=null, mxSession=null, mxFilter='all', modals=[], modalAnim=null, ctx={isAdmin:false,verifyAdmin:null}, adminErr='', adminBusy=false, adminEmail='', qzSession=null, focus={dur:25,left:1500,running:false,endAt:0,domain:'1',topic:''}, focusTimer=null, revNotes=null, rnDom='all', rnOnly=false;
