function manualUI(){if(!manGuide){fetchData('./data/manual-guide.json').then(d=>{manGuide=d;if(tab==='manual')layout()}).catch(e=>fail(e.message));return '<div class="cisa-empty cisa-section">Loading the manual…</div>'}
 manCheckPdf();const all=manSections(),R=state.manRead||{};if(!manSec)manSec=state.manLast||all[0].id;const cur=all.find(s=>s.id===manSec)||all[0],i=all.indexOf(cur),read=all.filter(s=>R[s.id]).length;
 const toc=manGuide.chapters.map(c=>`<div class="mn-ch"><div class="mn-ch-h"><b>${c.n}</b><span>${h(c.title)}</span><small>${c.weight}%</small></div>${c.parts.map(p=>`<div class="mn-part">Part ${p.id}: ${h(p.title)}</div>${p.sections.map(s=>`<button type="button" class="mn-sec ${s.id===cur.id?'on':''} ${R[s.id]?'read':''}" data-action="man-sec" data-id="${s.id}"><span class="mn-dot" aria-hidden="true">${R[s.id]?'✓':''}</span><span class="mn-no">${s.id}</span><span class="mn-t">${h(s.title)}${(state.manNotes||{})[s.id]?' ✎':''}</span></button>`).join('')}`).join('')}</div>`).join('');
 const seg=`<div class="mn-seg">${[['guide','Study guide'],['pdf','My PDF']].map(([k,l])=>`<button type="button" class="${manView===k?'on':''}" data-action="man-view" data-v="${k}">${l}</button>`).join('')}</div>`;
 const head=`<section class="mn-head"><div><div class="cisa-overline">CISA Review Manual · 28th edition structure</div><h2>CISA Manual</h2><p class="cisa-mini">${all.length} sections · <b>${read}</b> read · ${manPdfInfo?'your PDF is saved on this device':'add your own PDF to read the full text'}</p></div>${seg}</section><div class="mn-prog">${progress(pct(read,all.length))}</div>`;
 const pg=cur.page?`Manual p. ${cur.page}`:'';
 const guide=`<article class="mn-art"><div class="mn-crumb">Chapter ${cur.ch.n} · Part ${cur.part.id}: ${h(cur.part.title)}</div><h1><span>${cur.id}</span> ${h(cur.title)}</h1><div class="mn-meta">${pg?`<span>${pg}</span>`:''}<span>Syllabus ${h(cur.topic)}</span>${R[cur.id]?'<span class="ok">✓ Read</span>':''}</div><p class="mn-lead">${h(cur.summary)}</p>
  <div class="mn-tools">${button('man-listen',speaking?'⏹ Stop listening':'🔊 Listen to this section','sm')}<span class="cisa-mini">Tap a key point to highlight it ★</span></div>
  <h3>Key points</h3><ul class="mn-list">${cur.points.map((p,j)=>{const on=(state.manStars?.[cur.id]||[]).includes(j);return `<li class="${on?'star':''}" data-action="man-star" data-id="${cur.id}" data-i="${j}" title="Highlight">${h(p)}</li>`}).join('')}</ul>
  ${(cur.subs||[]).length?`<h3>In this section · ${cur.subs.length} subsections</h3><div class="mn-subs">${cur.subs.map(x=>`<details class="mn-sub" id="sub-${x.id.replace(/\./g,'-')}" ${manOpenSub===x.id?'open':''}><summary><span class="mn-sub-no">${x.id}</span><b>${h(x.title)}</b>${x.page?`<small>p. ${x.page}</small>`:''}</summary><div class="mn-sub-body"><ul>${x.points.map(p=>`<li>${h(p)}</li>`).join('')}</ul>${x.tip?`<div class="rn-tip"><b>Exam tip</b>${h(x.tip)}</div>`:''}${x.page?button('man-pdf','Read in my PDF · p. '+x.page,'sm',`data-page="${x.page}"`):''}</div></details>`).join('')}</div><div class="mn-subacts">${button('man-subs-all','Expand all','sm')}</div>`:''}
  ${cur.terms.length?`<h3>Key terms</h3><dl class="mn-terms">${cur.terms.map(t=>`<div><dt>${h(t.t)}</dt><dd>${h(t.d)}</dd></div>`).join('')}</dl>`:''}
  <div class="mn-two"><div class="mn-box aud"><h4>Auditor’s perspective</h4><ul>${cur.auditor.map(p=>`<li>${h(p)}</li>`).join('')}</ul></div><div class="mn-box trap"><h4>Exam traps</h4><ul>${cur.traps.map(p=>`<li>${h(p)}</li>`).join('')}</ul></div></div>
  <h3>My notes</h3><textarea class="mn-mynote" data-action="man-note" data-id="${cur.id}" rows="3" placeholder="Write your own notes for ${cur.id}. Saved to your account.">${h((state.manNotes||{})[cur.id]||'')}</textarea>
  <div class="mn-acts">${button('man-read',R[cur.id]?'Mark as unread':'Mark as read',R[cur.id]?'':'primary',`data-id="${cur.id}"`)}${cur.page?button('man-pdf','Read in my PDF · p. '+cur.page,'',`data-page="${cur.page}"`):''}${button('man-notes','Revision notes','',`data-dom="${cur.ch.n}"`)}</div>
  <nav class="mn-nav">${i>0?`<button type="button" data-action="man-sec" data-id="${all[i-1].id}"><small>Previous</small><b>${all[i-1].id} ${h(all[i-1].title)}</b></button>`:'<span></span>'}${i<all.length-1?`<button type="button" class="next" data-action="man-sec" data-id="${all[i+1].id}"><small>Next</small><b>${all[i+1].id} ${h(all[i+1].title)}</b></button>`:''}</nav>
  <p class="mn-note">${h(manGuide.edition)}</p></article>`;
 const marks=state.manMarks||[];
 const pdf=!manPdfUrl?`<article class="mn-art mn-drop"><h1>Add your CISA Review Manual</h1><p class="mn-lead">Choose your own PDF copy once. It is saved only in this browser on this device. It is never uploaded to GitHub, Firebase or anywhere else.</p><label class="mn-file"><input type="file" accept="application/pdf,.pdf" data-action="man-file"><span>Choose PDF…</span></label>${manErr?`<p class="pl-err">${h(manErr)}</p>`:''}<p class="cisa-mini">Large scanned PDFs (200+ MB) are fine on a laptop. On each new device or browser, add it again.</p></article>`
  :`<article class="mn-art mn-pdf"><div class="mn-bar"><select data-action="man-jump" aria-label="Jump to section"><option value="">Jump to section…</option>${all.filter(s=>s.page).map(s=>`<option value="${s.page}" ${manPage===s.page?'selected':''}>${s.id} ${h(s.title)} · p. ${s.page}</option>`).join('')}</select><form data-form="man-go" class="mn-go"><input type="number" name="p" min="1" max="600" placeholder="Page" value="${manPage||''}" aria-label="Manual page number"><button class="cisa-btn sm" type="submit">Go</button></form>${manPage?button('man-mark','☆ Bookmark p. '+manPage,'sm'):''}<span class="mn-sp"></span><label class="mn-off">Page offset <input type="number" data-action="man-offset" value="${manOffset()}" min="0" max="60"></label>${button('man-remove','Remove PDF','sm danger')}</div>
   ${marks.length?`<div class="mn-marks">${marks.map((m,j)=>`<span class="mn-mark"><button type="button" data-action="man-pdf" data-page="${m.p}">★ p. ${m.p}${m.l?' · '+h(m.l):''}</button><button type="button" class="x" data-action="man-unmark" data-i="${j}" aria-label="Remove bookmark">×</button></span>`).join('')}</div>`:''}
   <iframe class="mn-frame" title="CISA Review Manual" src="${manPdfUrl}#page=${(manPage||1)+(manPage?manOffset():0)}&view=FitH"></iframe><p class="cisa-mini">${h(manPdfInfo.name)} · ${(manPdfInfo.size/1048576).toFixed(0)} MB · page numbers match the printed manual (PDF page = printed page + ${manOffset()}).</p></article>`;
 return `<div class="cisa-section mn-wrap">${head}<div class="mn-grid"><aside class="mn-toc" aria-label="Manual contents">${toc}</aside><div class="mn-main">${manView==='pdf'?pdf:guide}</div></div></div>`}
function manOpenTopic(topicId){const s=manSections().find(x=>x.topic===topicId);if(s){manSec=s.id;state.manLast=s.id}manView='guide';tab='manual';modals=[];layout();window.scrollTo({top:0,behavior:'instant'})}

/* ---------- link a question to the manual section/subsection it tests ---------- */
const STOP=new Set('the a an of and or to in for on with by is are be as at that this which from it its an was were what when who most best first primary following should would will can auditor is organization organisation management audit'.split(' '));
const words=t=>String(t||'').toLowerCase().replace(/[^a-z0-9 ]/g,' ').split(/\s+/).filter(w=>w.length>3&&!STOP.has(w));
function manRef(q){if(!manGuide||!q)return null;const sec=manSections().find(s=>s.topic===q.topicId);if(!sec)return null;const qw=new Set(words(q.question+' '+(q.choices?.[q.answer]||'')+' '+(q.explanation||'')));let best=null,bs=0;for(const x of sec.subs||[]){const w=words(x.title+' '+x.points.join(' '));let sc=0;for(const v of new Set(w))if(qw.has(v))sc+=(words(x.title).includes(v)?2:1);if(sc>bs){bs=sc;best=x}}return {sec,sub:bs>=3?best:null}}
function manRefBtn(q){const r=manRef(q);if(!r)return '';const t=r.sub?`${r.sub.id} ${r.sub.title}`:`${r.sec.id} ${r.sec.title}`;const pg=(r.sub&&r.sub.page)||r.sec.page;return `<div class="mn-ref"><button type="button" data-action="man-ref" data-sec="${r.sec.id}" data-sub="${r.sub?r.sub.id:''}">📖 Read ${h(t)} in the manual${pg?` · p. ${pg}`:''}</button></div>`}
function ensureManGuide(){if(!manGuide)fetchData('./data/manual-guide.json').then(d=>{manGuide=d;if(['mocks','mistakes','result','overview'].includes(tab))layout()}).catch(()=>{})}

/* ---------- Daily study coach ---------- */
function coachPick(){const scores=domainScore(),R=state.manRead||{};
 const rank=scores.map(d=>{const acc=d.accuracy;const weak=acc===null?0.55:Math.max(0.05,1-acc/100);const unread=manGuide?manSections().filter(s=>s.ch.n===d.domain&&!R[s.id]).length:1;return {d,score:d.weight*weak*(unread?1:0.4)}}).sort((a,b)=>b.score-a.score);
 const dom=rank[0].d.domain;const wt=new Map(weakTopics().map(x=>[x.topic.id,x]));
 const secs=manGuide?manSections().filter(s=>s.ch.n===dom):[];
 const pick=[...secs].sort((a,b)=>((R[a.id]?1:0)-(R[b.id]?1:0))||((wt.get(a.topic)?.accuracy??101)-(wt.get(b.topic)?.accuracy??101)))[0];
 return {d:dateStr(new Date()),dom,sec:pick?pick.id:null,topic:pick?pick.topic:null,notes:false,quiz:false}}
function coachToday(){const t=dateStr(new Date());if(!state.coach||state.coach.d!==t||(!state.coach.sec&&manGuide)){state.coach=coachPick();persist()}return state.coach}
function coachCard(){if(!manGuide){ensureManGuide();return ''}const c=coachToday(),sec=manSections().find(s=>s.id===c.sec),dm=syllabus.domains.find(d=>d.id==c.dom),sc=domainScore().find(d=>d.domain==c.dom),R=state.manRead||{};
 const steps=[{k:'read',done:!!(sec&&R[sec.id]),t:sec?`Read ${sec.id} ${sec.title}`:'Read a manual section',s:'Manual study guide, then press “Mark as read”',b:button('coach-read','Open section','sm primary')},
  {k:'notes',done:!!c.notes,t:`Review revision notes for ${sec?sec.topic:'D'+c.dom}`,s:'Short exam points and tips',b:button('coach-notes','Open notes','sm')},
  {k:'quiz',done:!!c.quiz,t:`10-question quiz · Domain ${c.dom}`,s:'Wrong answers go to your Mistakes notebook',b:button('coach-quiz','Start quiz','sm')}];
 const n=steps.filter(x=>x.done).length;
 return `<section class="ed-card coach"><div class="coach-head"><div><span class="ed-kicker">Today’s coach</span><h3 class="ed-title">Domain ${c.dom} · ${h(dm?dm.name:'')}</h3><p class="ed-sub">${dm?dm.weight:''}% of the exam${sc&&sc.accuracy!==null?` · your accuracy ${sc.accuracy}%`:' · not practised yet'} · picked because it gives the most marks to gain today.</p></div><div class="coach-ring"><b>${n}/3</b><span>done</span></div></div><ol class="coach-steps">${steps.map((x,i)=>`<li class="${x.done?'done':''}"><span class="coach-n">${x.done?'✓':i+1}</span><div><b>${h(x.t)}</b><small>${h(x.s)}</small></div>${x.done?'<span class="coach-ok">Done</span>':x.b}</li>`).join('')}</ol>${n===3?'<p class="coach-fin">Great work, today’s coaching is complete. Come back tomorrow for the next step.</p>':''}</section>`}
export async function coachInfo(read){const ti=await todayInfo(read);if(!manGuide){try{manGuide=await fetchData('./data/manual-guide.json')}catch(e){}}const saved=state;try{state=Object.assign(defaultState(),read()||{});ensureImported();const c=(state.coach&&state.coach.d===dateStr(new Date()))?state.coach:coachPick();const sec=manSections().find(s=>s.id===c.sec);const done=[!!(sec&&(state.manRead||{})[sec.id]),!!c.notes,!!c.quiz].filter(Boolean).length;return {...ti,coach:{dom:c.dom,sec:sec?sec.id+' '+sec.title:'',done}}}finally{state=saved}}

function manSpeak(sec){try{const ss=window.speechSynthesis;if(!ss)return info('Listening is not supported in this browser.');ss.cancel();if(speaking){speaking=false;layout();return}
 const parts=[`${sec.id}. ${sec.title}.`,sec.summary,'Key points.',...sec.points,...(sec.subs||[]).flatMap(x=>[`${x.id}. ${x.title}.`,...x.points]),'Exam traps.',...sec.traps];
 speaking=true;parts.forEach((t,i)=>{const u=new SpeechSynthesisUtterance(t);u.rate=1;u.lang='en-GB';if(i===parts.length-1)u.onend=()=>{speaking=false;if(tab==='manual')layout()};ss.speak(u)});layout()}catch(e){speaking=false}}

/* ---------- Admin: learner progress ---------- */
function learnerSummary(data){const saved=state;try{state=Object.assign(defaultState(),(data&&data.cisa)||{});ensureImported();const p=getPlan(),c=totalComplete(),rd=readiness(),now=dateStr(new Date());
 const firsts=MOCK_IDS.map(id=>{const r=firstResult(id);return r?{id,p:pct(r.correct,r.total)}:null}).filter(Boolean);const q=(state.quizzes||[]).slice(-5);
 return {mode:state.planMode,locked:!!(state.planLock&&state.planLock.locked),lockAt:state.planLock&&state.planLock.at,exam:p.examDate,days:Math.max(0,dayDiff(now,p.examDate)),done:c.done,total:c.total,ready:rd?rd.percent:null,mocks:firsts,quiz:q.length?Math.round(q.reduce((a,x)=>a+x.right/x.n,0)/q.length*100):null,mx:mxDue().length,hours:(state.logs.reduce((a,l)=>a+Number(l.minutes||0),0)/60).toFixed(1),manual:Object.keys(state.manRead||{}).length,notes:Object.keys(state.revNotes||{}).length,last:data&&data.t?new Date(data.t):null,scores:domainScore()}}finally{state=saved}}
export async function learnerSnapshot(data){if(!syllabus){[syllabus,templates.normal,templates.relaxed]=await Promise.all([fetchData('./data/syllabus.json'),fetchData('./data/normal-plan.json'),fetchData('./data/relaxed-plan.json')])}const s=learnerSummary(data);const saved=state;try{state=Object.assign(defaultState(),(data&&data.cisa)||{});ensureImported();s.topicNames=Object.fromEntries(allTopics().map(t=>[t.id,titleOf(t)]));s.mockTitles=Object.fromEntries(MOCKS.map(m=>[m.id,m.title]))}catch(e){}finally{state=saved}return s}
function learnersUI(){if(!ctx.isAdmin)return '<div class="cisa-empty cisa-section">Admin only.</div>';
 if(!learners&&!learnersBusy&&ctx.readLearners){learnersBusy=true;ctx.readLearners().then(r=>{learners=r;learnersBusy=false;if(tab==='learners')layout()}).catch(()=>{learners=[];learnersBusy=false;if(tab==='learners')layout()})}
 if(!learners)return '<div class="cisa-empty cisa-section">Loading learner progress…</div>';
 if(!learners.length)return '<div class="cisa-empty cisa-section">No other approved accounts.</div>';
 return `<div class="cisa-section">${button('learners-refresh','↻ Refresh','sm')}</div>`+learners.map(L=>{if(!L.ok)return `<section class="cisa-card cisa-section"><h2>Account ${h(L.uid.slice(0,8))}…</h2><p class="pl-err">Cannot read this account (${h(L.error)}). Publish the new <code>firestore.rules</code> in the Firebase Console so the admin can read learner progress.</p></section>`;if(!L.data)return `<section class="cisa-card cisa-section"><h2>Account ${h(L.uid.slice(0,8))}…</h2><p class="cisa-mini">No progress saved yet.</p></section>`;
  const s=learnerSummary(L.data);
  return `<section class="ed-card lr"><div class="lr-head"><div><span class="ed-kicker">Learner · ${h(L.uid.slice(0,8))}…</span><h3 class="ed-title">${s.mode==='relaxed'?'Relaxed':'Normal'} plan ${s.locked?'· 🔒 locked':'· not locked'}</h3><p class="ed-sub">Exam ${h(fmtDate(s.exam))} · ${s.days} days left · last active ${s.last?h(s.last.toLocaleString()):'unknown'}</p></div>${s.locked?button('learner-unlock','Unlock plan','sm',`data-uid="${h(L.uid)}"`):''}</div>
  <div class="lr-stats"><div><b>${s.ready===null?'–':s.ready+'%'}</b><span>readiness</span></div><div><b>${s.done}/${s.total}</b><span>topics done</span></div><div><b>${s.hours}h</b><span>logged</span></div><div><b>${s.quiz===null?'–':s.quiz+'%'}</b><span>recent quizzes</span></div><div><b>${s.mx}</b><span>mistakes due</span></div><div><b>${s.manual}/60</b><span>manual read</span></div></div>
  <div class="lr-doms">${s.scores.map(d=>`<div><span>D${d.domain}</span>${progress(d.accuracy??0)}<small>${d.accuracy===null?'no data':d.accuracy+'%'} · ${d.coverage}% covered</small></div>`).join('')}</div>
  <p class="cisa-mini">Mock first attempts: ${s.mocks.length?s.mocks.map(m=>`Mock ${m.id} ${m.p}%`).join(' · '):'none yet'} · revision notes revised: ${s.notes}</p></section>`}).join('')}

function modalsUI(){if(!modals.length)return '';const p=getPlan();const def={plan:{title:h(p.title),sub:`${h(fmtDate(p.start))} → ${h(fmtDate(p.examDate))} · ${state.planMode==='normal'?'Normal':'Relaxed'} plan`,body:planFullUI,foot:locked()?`${button('plan-ics','Add to calendar')}${button('modal-close','Done','primary')}`:`${button('plan-ics','Add to calendar')}${button('modal-close','Done')}${button('plan-config','Set up plan','primary')}`},config:{title:'Set up your plan',sub:'One-time setup · dates, weekly hours and topics',body:planConfigUI,foot:`${button('modal-close','Cancel')}<button type="submit" form="cisaPlanForm" class="cisa-btn primary">Save &amp; lock plan</button>`},ics:{title:'Add to calendar',sub:'Your study plan as calendar events',body:icsUI,foot:`${button('modal-close','Cancel')}<button type="submit" form="cisaIcsForm" class="cisa-btn primary">Download .ics</button>`},admin:{title:'Admin unlock',sub:'The admin signs in here to unlock this plan',body:adminUI,foot:`${button('modal-close','Cancel')}<button type="submit" form="cisaAdminForm" class="cisa-btn primary" ${adminBusy?'disabled':''}>${adminBusy?'Checking…':'Unlock plan'}</button>`}};
 return modals.map((m,i)=>{const d=def[m];return `<div class="ap-modal ${i<modals.length-1?'is-under':''} ${modalAnim===m?'anim':''}" data-modal="${m}" role="dialog" aria-modal="true" aria-label="${d.title}"><div class="ap-backdrop" data-action="modal-close"></div><div class="ap-sheet ap-${m}"><header class="ap-head"><button type="button" class="ap-x" data-action="modal-close" aria-label="Close">×</button><div><h3>${d.title}</h3><p>${d.sub}</p></div></header><div class="ap-body" data-scroll="${m}">${d.body()}</div><footer class="ap-foot">${d.foot}</footer></div></div>`}).join('')}
function layout(){if(!root)return; if(tab==='exam'){root.innerHTML='<div class="cisa-hub">'+examUI()+'</div>';attach();return}if(tab==='result'){root.innerHTML='<div class="cisa-hub">'+resultUI(examBank?.id||1)+'</div>';attach();return}let content={learners:learnersUI,overview,planner,manual:manualUI,syllabus:syllabusUI,recorder,revision:revisionsUI,mocks:mocksUI,mistakes:mistakesUI,analytics:analyticsUI,notes:notesUI};const keep={};root.querySelectorAll('.ap-body[data-scroll]').forEach(b=>keep[b.dataset.scroll]=b.scrollTop);root.innerHTML='<div class="cisa-hub">'+header()+(content[tab]||overview)()+modalsUI()+'</div>';root.querySelectorAll('.ap-body[data-scroll]').forEach(b=>{if(keep[b.dataset.scroll])b.scrollTop=keep[b.dataset.scroll]});modalAnim=null;document.documentElement.classList.toggle('ap-lock',modals.length>0);attach();}
function attach(){if(timer){clearInterval(timer);timer=null}if(tab==='exam'){timer=setInterval(()=>{const draft=state.drafts[examBank?.id];if(!draft)return;if(Date.now()>=draft.endAt){clearInterval(timer);finishMock(examBank.id,true);tab='result';reviewQuestion=0;layout();return}const el=$('[data-time]');if(el)el.textContent=timeLeft(draft.endAt)},1000)}if(tab==='recorder'&&stopwatchStart)beginWatch()}
function navigate(t){if(speaking){try{speechSynthesis.cancel()}catch(e){}speaking=false}if(timer){clearInterval(timer);timer=null}if(t!=='mistakes')mxSession=null;if(t!=='mocks')qzSession=null;tab=t;editTopic=null;modals=[];focusedTopic=null;layout();window.scrollTo({top:0,behavior:'instant'})}
function download(filename,content,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csv(rows){return rows.map(row=>row.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(',')).join('\r\n')}
function info(msg){uiAlert(msg)}
function migrateDraft(id){const d=state.drafts[id],b=bankCache[id];if(!d||!b||(d.v||1)>=(b.version||1))return;for(const qid of b.rewrittenInV2||[])delete d.answers[qid];d.v=b.version;persist()}
async function loadBank(id,setCurrent=true){bankCache[id]??=await fetchData(`./mock-exams/mock-${String(id).padStart(2,'0')}.json`);migrateDraft(id);if(setCurrent)examBank=bankCache[id];return bankCache[id]}
function finishMock(id,auto=false){const draft=state.drafts[id];if(!draft||!examBank||examBank.id!==id)return;const data=examBank.questions,stats={},topicStats={},wrong=[];let correct=0;for(const q of data){const hit=draft.answers[q.id]===q.answer;if(hit)correct++;else wrong.push({id:q.id,topicId:q.topicId});stats[q.domain]??={total:0,correct:0};stats[q.domain].total++;if(hit)stats[q.domain].correct++;topicStats[q.topicId]??={total:0,correct:0};topicStats[q.topicId].total++;if(hit)topicStats[q.topicId].correct++;}const attempt=(state.mockAttempts[id]||0)+1;state.mockAttempts[id]=attempt;const r={id:'r'+Date.now(),mockId:id,attempt,date:new Date().toISOString(),correct,total:data.length,unanswered:data.length-Object.keys(draft.answers).length,elapsed:Math.min(Date.now()-draft.startedAt,240*60000),stats,topicStats,wrong,answers:draft.answers,order:draft.order||'',v:draft.v||1,auto};for(const w of wrong)if(draft.answers[w.id]!==undefined)mxAddWrong(w.id,id);state.results.push(r);track(`Completed mock exam ${id} (${mockMeta(id).title}): ${correct}/${data.length} · ${pct(correct,data.length)}%${attempt>1?' · retake '+attempt:''}`,'CISA · Mock exams');state.results=trimResults(state.results);delete state.drafts[id];state.activeMock=null;persist()}
function updateDraft(){persist();layout()}
function beginWatch(){if(stopWatch)clearInterval(stopWatch);stopWatch=setInterval(()=>{const el=$('#cisa-study-timer');if(el){const s=Math.floor((Date.now()-stopwatchStart+stopwatchElapsed)/1000);el.textContent=pad(Math.floor(s/60))+':'+pad(s%60)}},1000)}
function closeModal(){if(!modals.length)return;const top=root.querySelector('.ap-modal:last-of-type');const done=()=>{const m=modals.pop();if(m==='config')editTopic=null;layout()};if(top&&!matchMedia('(prefers-reduced-motion: reduce)').matches){top.classList.add('closing');setTimeout(done,190)}else done()}
document.addEventListener('keydown',e=>{if(!root||!document.body.contains(root)||tab!=='exam'||examReview||e.metaKey||e.ctrlKey||e.altKey||e.target.closest('input,textarea,select'))return;const k=e.key.toLowerCase();const go=sel=>{const b=root.querySelector(sel);if(b&&!b.disabled){e.preventDefault();b.click()}};if('abcd'.includes(k)&&k.length===1)go(`.cisa-answers .cisa-answer:nth-child(${'abcd'.indexOf(k)+1})`);else if(k==='n'||e.key==='ArrowRight')go('[data-action="mock-next"]');else if(k==='p'||e.key==='ArrowLeft')go('[data-action="mock-prev"]');else if(k==='f')go('[data-action="flag"]')});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modals.length&&root&&document.body.contains(root)){e.preventDefault();closeModal()}});
function action(ev){const btn=ev.target.closest('[data-action]');if(!btn||!root.contains(btn))return;const a=btn.dataset.action,id=btn.dataset.topic,mode=btn.dataset.mock&&Number(btn.dataset.mock);if(btn.type==='checkbox'||btn.type==='file'||btn.type==='number'||btn.tagName==='SELECT')return;let previousScroll=window.scrollY;
 if(a==='learners-refresh'){learners=null;layout();return}
 if(a==='learner-unlock'){ask('They can set up and lock a new plan afterwards.',{title:'Unlock this learner’s study plan?',ok:'Unlock'},()=>{ctx.unlockLearner&&ctx.unlockLearner(btn.dataset.uid).then(ok=>{info(ok?'Plan unlocked.':'Could not unlock. Check the Firestore rules are published.');learners=null;layout()})});return}
 if(a==='man-listen'){const sec=manSections().find(x=>x.id===manSec);if(sec)manSpeak(sec);return}
 if(a==='man-star'){const id=btn.dataset.id,j=+btn.dataset.i;state.manStars=state.manStars||{};const arr=new Set(state.manStars[id]||[]);arr.has(j)?arr.delete(j):arr.add(j);state.manStars[id]=[...arr];persist();btn.classList.toggle('star');return}
 if(a==='coach-read'){const c=coachToday();manSec=c.sec;state.manLast=c.sec;manView='guide';tab='manual';layout();window.scrollTo({top:0,behavior:'instant'});return}
 if(a==='coach-notes'){const c=coachToday();c.notes=true;persist();rnDom=String(c.dom);rnOnly=false;tab='revision';layout();window.scrollTo({top:0,behavior:'instant'});return}
 if(a==='coach-quiz'){const c=coachToday();loadAllBanks().then(()=>qzBegin(10,c.dom)).catch(e=>fail(e.message));return}
 if(a==='man-ref'){manSec=btn.dataset.sec;manOpenSub=btn.dataset.sub||null;state.manLast=manSec;manView='guide';tab='manual';mxSession=null;qzSession=null;layout();window.scrollTo({top:0,behavior:'instant'});if(manOpenSub)setTimeout(()=>document.getElementById('sub-'+manOpenSub.replace(/\./g,'-'))?.scrollIntoView({block:'center'}),80);return}
 if(a==='man-subs-all'){root.querySelectorAll('.mn-sub').forEach(d=>d.open=true);return}
 if(a==='man-view'){manView=btn.dataset.v;layout();return}
 if(a==='man-sec'){manSec=btn.dataset.id;state.manLast=manSec;persist();manView='guide';layout();root.querySelector('.mn-main')?.scrollIntoView({block:'start',behavior:'instant'});return}
 if(a==='man-read'){const i=btn.dataset.id;state.manRead=state.manRead||{};if(state.manRead[i])delete state.manRead[i];else{state.manRead[i]=dateStr(new Date());const x=manSections().find(z=>z.id===i);track(`Read manual section ${i}${x?' '+x.title:''}`,'CISA · Manual')}persist();layout();return}
 if(a==='man-pdf'){manPage=+btn.dataset.page||null;manView='pdf';layout();return}
 if(a==='man-notes'){rnDom=btn.dataset.dom;tab='revision';layout();window.scrollTo({top:0,behavior:'instant'});return}
 if(a==='man-mark'){if(!manPage)return;const l=(prompt('Bookmark label (optional)','')||'').slice(0,40);state.manMarks=[...(state.manMarks||[]).filter(m=>m.p!==manPage),{p:manPage,l}].sort((x,y)=>x.p-y.p);persist();layout();return}
 if(a==='man-unmark'){state.manMarks=(state.manMarks||[]).filter((m,j)=>j!==+btn.dataset.i);persist();layout();return}
 if(a==='man-remove'){ask('You can add it again any time. Your notes and highlights stay.',{title:'Remove the manual PDF from this device?',ok:'Remove',danger:true},()=>{manIdbDel().then(()=>{if(manPdfUrl)URL.revokeObjectURL(manPdfUrl);manPdfUrl=null;manPdfInfo=null;layout()})});return}
 if(a==='man-topic'){manOpenTopic(btn.dataset.topic);return}
 if(a==='rn-dom'){rnDom=btn.dataset.dom;layout();return}
 if(a==='rn-open'){const i=btn.dataset.id;rnOpen.has(i)?rnOpen.delete(i):rnOpen.add(i);return}
 if(a==='rn-mark'){const i=btn.dataset.id;state.revNotes=state.revNotes||{};if(state.revNotes[i])delete state.revNotes[i];else{state.revNotes[i]=dateStr(new Date());const c=(revNotes&&revNotes.cards||[]).find(z=>z.id===i);track(`Revised note: ${c&&c.title||i}`,'CISA · Revision')}persist();layout();return}
 if(a==='qz-10'||a==='qz-25'){loadAllBanks().then(()=>qzBegin(a==='qz-10'?10:25)).catch(e=>fail(e.message));return}
 if(a==='qz-pick'){if(!qzSession||qzSession.picked!==null)return;const id=qzSession.queue[qzSession.pos],q=qIndex.get(id),o=Number(btn.dataset.option),ok=o===q.answer;qzSession.picked=o;const dm=qzSession.dom[q.domain]||(qzSession.dom[q.domain]=[0,0]);dm[1]++;if(ok){qzSession.right++;dm[0]++}else mxAddWrong(id,q.mockId);state.qzSeen=[...(state.qzSeen||[]).filter(x=>x!==id),id].slice(-600);persist();layout();return}
 if(a==='qz-next'){if(!qzSession)return;qzSession.pos++;qzSession.picked=null;if(qzSession.pos>=qzSession.queue.length){if(qzSession.coach){const c=coachToday();c.quiz=true}state.quizzes=[...(state.quizzes||[]),{at:new Date().toISOString(),n:qzSession.queue.length,right:qzSession.right,dom:qzSession.dom}].slice(-100);persist();track(`Finished quick quiz: ${qzSession.right}/${qzSession.queue.length} · ${pct(qzSession.right,qzSession.queue.length)}%`,'CISA · Quick quiz')}layout();window.scrollTo({top:0,behavior:'instant'});return}
 if(a==='qz-end'){if(qzSession&&qzSession.pos>0&&qzSession.pos<qzSession.queue.length){const n=qzSession.pos;state.quizzes=[...(state.quizzes||[]),{at:new Date().toISOString(),n,right:qzSession.right,dom:qzSession.dom,partial:true}].slice(-100);persist();track(`Ended quick quiz early: ${qzSession.right}/${n}`,'CISA · Quick quiz')}qzSession=null;layout();return}
 if(a==='plan-ics'){if(!modals.includes('ics')){modals=[...modals,'ics'];modalAnim='ics'}layout();return}
 if(a==='focus-len'){if(focus.running)return;focus.dur=+btn.dataset.min;focus.left=focus.dur*60;layout();return}
 if(a==='focus-start'){focus.running=true;focus.endAt=Date.now()+focus.left*1000;try{if('Notification' in window&&Notification.permission==='default')Notification.requestPermission()}catch(e){}clearInterval(focusTimer);focusTimer=setInterval(focusTick,1000);layout();return}
 if(a==='focus-pause'){focus.left=focusLeft();focus.running=false;clearInterval(focusTimer);focusTimer=null;layout();return}
 if(a==='focus-reset'){focus.running=false;clearInterval(focusTimer);focusTimer=null;focus.left=focus.dur*60;layout();return}
 if(locked()&&LOCKED_ACTIONS.includes(a)){info('Your study plan is locked. Ask the admin to unlock it.');return}
 if(a==='admin-auth'){adminErr='';if(!modals.includes('admin')){modals=[...modals,'admin'];modalAnim='admin'}layout();setTimeout(()=>root.querySelector('#cisaAdminForm input')?.focus(),60);return}
 if(a==='admin-unlock'){if(!ctx.isAdmin)return;ask('The learner can then set up and lock a new plan.',{title:'Unlock this study plan?',ok:'Unlock'},()=>{state.planLock={locked:false,unlockedAt:new Date().toISOString()};persist();layout()});return}
 if(a==='nav'){navigate(btn.dataset.target);return}
 if(a==='mx-start'||a==='mx-start-all'||a==='mx-one'){loadAllBanks().then(()=>{let ids;if(a==='mx-one')ids=[btn.dataset.id];else{const pool=(a==='mx-start'?mxDue():mxActive()).filter(c=>qIndex.has(c.id)).sort((x,y)=>x.d.localeCompare(y.d)||(y.w||1)-(x.w||1));ids=pool.slice(0,a==='mx-start'?50:30).map(c=>c.id)}if(ids.length)mxBegin(ids)}).catch(e=>fail(e.message));return}
 if(a==='mx-pick'){if(!mxSession||mxSession.picked!==null)return;const id=mxSession.queue[mxSession.pos],q=qIndex.get(id),o=Number(btn.dataset.option),ok=o===q.answer;mxSession.picked=o;if(ok)mxSession.right++;mxRecord(id,ok);persist();layout();return}
 if(a==='mx-next'){if(!mxSession)return;mxSession.pos++;mxSession.picked=null;layout();window.scrollTo({top:0,behavior:'instant'});return}
 if(a==='mx-end'){if(mxSession){const n=mxSession.pos+(mxSession.picked!==null?1:0);if(n)track(`Reviewed ${n} mistake${n===1?'':'s'}: ${mxSession.right} correct`,'CISA · Mistakes review')}mxSession=null;layout();return}
 if(a==='mx-remove'){ask('It won’t come back for review.',{title:'Remove from your Mistakes notebook?',ok:'Remove',danger:true},()=>{delete state.mistakes[btn.dataset.id];persist();layout()});return}

 if(a==='mode-normal'||a==='mode-relaxed'){state.planMode=a.endsWith('normal')?'normal':'relaxed';weekIndex=0;persist();layout();return}
 if(a==='prev-week'||a==='next-week'||a==='today-week'){weekIndex=a==='prev-week'?weekIndex-1:a==='next-week'?weekIndex+1:clamp(Math.floor(dayDiff(getPlan().start,dateStr(new Date()))/7),0,99);layout();return}
 if(a==='reset-plan'){ask('Completed work and notes stay as they are.',{title:'Restore the default dates and study hours?',ok:'Restore'},()=>{state.plans[state.planMode]=structuredClone(templates[state.planMode]);persist();layout()});return}
 if(a==='plan-open'){modals=['plan'];modalAnim='plan';layout();return}
 if(a==='plan-config'){if(!modals.includes('config')){modals=[...modals.filter(m=>m!=='config'),'config'];modalAnim='config'}layout();return}
 if(a==='modal-close'){closeModal();return}
 if(a==='edit-topic'||a==='new-topic'){editTopic=a==='new-topic'?'new':id;if(tab!=='planner'){tab='planner'}if(!modals.includes('config')){modals=[...modals,'config'];modalAnim='config'}layout();requestAnimationFrame(()=>{const f=root.querySelector('.ap-config form[data-form="topic"]');if(f)f.scrollIntoView({block:'start',behavior:'smooth'})});return}
 if(a==='cancel-edit'){editTopic=null;layout();return}
 if(a==='open-topic'){focusedTopic=id;tab=tab==='revision'?'revision':'syllabus';layout();$('#cisa-topic-detail')?.scrollIntoView({block:'start'});return}
 if(a==='close-topic'){focusedTopic=null;layout();return}
 if(a==='complete-toggle'){state.complete[id]=!state.complete[id];if(state.complete[id])track(`Completed topic ${topicName(id)}`,'CISA · Course & syllabus');persist();layout();return}
 if(a==='move-up'||a==='move-down'){const arr=allTopics().map(x=>x.id),i=arr.indexOf(id),j=i+(a==='move-up'?-1:1);if(j>=0&&j<arr.length){[arr[i],arr[j]]=[arr[j],arr[i]];state.order=arr;persist();layout()}return}
 if(a==='delete-custom'){ask('',{title:'Delete this custom task?',ok:'Delete',danger:true},()=>{state.customTasks=state.customTasks.filter(x=>x.id!==id);state.order=state.order.filter(x=>x!==id);state.hidden=state.hidden.filter(x=>x!==id);delete state.complete[id];delete state.topicEdits[id];persist();layout()});return}
 if(a==='delete-log'){ask('',{title:'Delete this study record?',ok:'Delete',danger:true},()=>{state.logs=state.logs.filter(x=>x.id!==btn.dataset.id);persist();layout()});return}
 if(a==='schedule-review'||a==='review-done'){const count=state.revisionCounts[id]||0;const intervals=[1,3,7,14];if(a==='review-done')state.revisionCounts[id]=count+1;const date=dateAdd(dateStr(new Date()),a==='schedule-review'?1:intervals[Math.min(count,3)]);state.revisions[id]=date;persist();layout();return}
 if(a==='remove-review'){delete state.revisions[id];persist();layout();return}
 if(a==='catchup'){let ds=dateStr(new Date()),p=getPlan();if(ds<p.start)ds=p.start;for(let n=0;n<365;n++,ds=dateAdd(ds,1)){if((p.weeklyMinutes||[])[dayIdx(ds)]>0)break}if(ds>p.examDate){info('No remaining study day before your exam target. Edit the plan dates or weekly hours.');return}state.topicEdits[id]={...(state.topicEdits[id]||{}),date:ds};persist();layout();return}
 if(a==='timer-start'){if(!stopwatchStart){stopwatchStart=Date.now()}beginWatch();return}
 if(a==='timer-stop'){if(stopwatchStart){stopwatchElapsed+=Date.now()-stopwatchStart;stopwatchStart=null}clearInterval(stopWatch);const el=$('#cisa-duration');if(el)el.value=Math.max(1,Math.ceil(stopwatchElapsed/60000));return}
 if(a==='export-json'){download('cisa-backup-'+dateStr(new Date())+'.json',JSON.stringify({kind:'jslearning-cisa-v1',data:state},null,2),'application/json');return}
 if(a==='export-csv'){download('cisa-study-records.csv',csv([['Date','Domain','Topic','Minutes','Questions','Correct','Confidence','Notes'],...state.logs.map(x=>[x.date,x.domain,x.topicId,x.minutes,x.questions,x.correct,x.confidence,x.notes])]),'text/csv');return}
 if(a==='export-plan'){
   const t=timeline();
   const rows=[['Date','Task','Domain','Minutes','Complete']];
   for(const d of t.days){for(const x of t.byday[d]){
     rows.push([d,x.topic?titleOf(x.topic):x.mock?'Mock '+x.mock:'Target CISA exam',x.topic?x.topic.domain:'',x.minutes,x.topic?!!state.complete[x.topic.id]:'']);
   }}
   download('cisa-planner-'+state.planMode+'.csv',csv(rows),'text/csv');return;
 }
 if(a==='note-open'){focusedTopic=id;tab='notes';layout();return}
 if(a==='mock-start'){const goExam=()=>{tab='exam';examPage=0;loadBank(mode).then(()=>layout()).catch(e=>fail(e.message));layout()};if(!state.drafts[mode]){ask(`${mockMeta(mode).n} questions · ${mockMeta(mode).min} minutes. The timer keeps running if you leave the page.`,{title:`Start Mock exam ${mode}?`,ok:'Start exam'},()=>{state.drafts[mode]={startedAt:Date.now(),endAt:Date.now()+mockMeta(mode).min*60000,answers:{},flags:[],order:makeOrder(mockMeta(mode).n),v:mode===4?1:2};persist();track(`Started mock exam ${mode} (${mockMeta(mode).title})`,'CISA · Mock exams');goExam()});return}goExam();return}
 if(a==='mock-result'){tab='result';reviewQuestion=0;loadBank(mode).then(()=>layout()).catch(e=>fail(e.message));layout();return}
 if(a==='choose'){const d=state.drafts[examBank.id],q=examBank.questions[examPage];d.answers[q.id]=Number(btn.dataset.option);updateDraft();return}
 if(a==='flag'){const d=state.drafts[examBank.id],q=examBank.questions[examPage];d.flags.includes(q.id)?d.flags=d.flags.filter(x=>x!==q.id):d.flags.push(q.id);updateDraft();return}
 if(a==='mock-go'||a==='mock-prev'||a==='mock-next'){examReview=false;examPage=a==='mock-go'?Number(btn.dataset.q):clamp(examPage+(a==='mock-prev'?-1:1),0,examBank.questions.length-1);layout();window.scrollTo({top:0,behavior:'instant'});return}
 if(a==='mock-submit'){examReview=true;layout();window.scrollTo({top:0,behavior:'instant'});return}
 if(a==='exam-back'){examReview=false;layout();return}
 if(a==='mock-submit-final'){const d=state.drafts[examBank.id];const remaining=examBank.questions.length-Object.keys(d.answers).length;ask(remaining?`${remaining} question${remaining===1?' is':'s are'} still unanswered. You’ll see your score and explanations next.`:'You’ll see your score and explanations next.',{title:'Submit this mock exam?',ok:'Submit'},()=>{examReview=false;finishMock(examBank.id);tab='result';reviewQuestion=0;layout()});return}
 if(a==='result-prev'||a==='result-next'){reviewQuestion=clamp(reviewQuestion+(a==='result-prev'?-1:1),0,examBank.questions.length-1);layout();return}
 if(a==='mock-reset'){ask('Your earlier results are kept.',{title:'Start a fresh attempt?',ok:'Start again'},()=>{delete state.drafts[mode];persist();tab='mocks';layout()});return}
 }
function changes(e){const el=e.target;if(!el.dataset.action)return;
 if(el.dataset.action==='man-file'){const f=el.files&&el.files[0];if(!f)return;if(!/pdf$/i.test(f.type)&&!/\.pdf$/i.test(f.name)){manErr='Please choose a PDF file.';layout();return}manErr='';const v={blob:f,name:f.name,size:f.size,at:new Date().toISOString()};manIdbPut(v).then(()=>{manPdfInfo={name:f.name,size:f.size,at:v.at};manPdfUrl=URL.createObjectURL(f);layout()}).catch(err=>{manErr='This browser could not store the file ('+(err&&err.message||'storage limit')+'). Try Chrome or Safari on a laptop with free disk space.';layout()});return}
 if(el.dataset.action==='man-note'){state.manNotes=state.manNotes||{};const v=el.value.slice(0,4000);if(v)state.manNotes[el.dataset.id]=v;else delete state.manNotes[el.dataset.id];persist();return}
 if(el.dataset.action==='man-jump'){manPage=+el.value||null;layout();return}
 if(el.dataset.action==='man-offset'){state.manOffset=Math.max(0,Math.min(60,+el.value||0));persist();layout();return}const a=el.dataset.action,id=el.dataset.topic;if(a==='note-switch'){focusedTopic=el.value;layout();return}if(a==='mx-filter'){mxFilter=el.value;layout();return}if(a==='rn-only'){rnOnly=el.checked;layout();return}if(a==='focus-domain'){focus.domain=el.value;focus.topic='';layout();return}if(a==='focus-topic'){focus.topic=el.value;return}if(a==='complete'){state.complete[id]=el.checked;if(el.checked)track(`Completed topic ${topicName(id)}`,'CISA · Course & syllabus');persist();layout();return}if(a==='include'&&locked()){el.checked=!el.checked;info('Your study plan is locked. Ask the admin to unlock it.');return}if(a==='include'){state.hidden=el.checked?state.hidden.filter(x=>x!==id):[...new Set([...state.hidden,id])];persist();layout();return}if(a==='registered'||a==='booked'){state.registration[a]=el.checked;persist();return}}
async function submit(e){const f=e.target;if(!f.dataset.form)return;e.preventDefault();const v=Object.fromEntries(new FormData(f));const n=f.dataset.form;
 if((n==='plan'||n==='topic')&&locked()){info('Your study plan is locked. Ask the admin to unlock it.');return}
 if(n==='man-go'){manPage=Math.max(1,Math.min(600,+v.p||1));layout();return}
 if(n==='ics'){const r=buildIcs(String(v.time||'19:00'),String(v.alarm||'0'));state.icsTime=v.time;state.icsAlarm=v.alarm;persist();if(!r.n){info('There are no study days left in your plan to export.');return}dlFile("cisa-study-plan.ics",r.text,"text/calendar");modals=modals.filter(m=>m!=='ics');layout();return}
 if(n==='admin'){if(adminBusy)return;adminEmail=String(v.email||'').trim();if(!ctx.verifyAdmin){adminErr='Admin check is not available.';layout();return}adminBusy=true;adminErr='';layout();let r=null;try{r=await ctx.verifyAdmin(String(v.email||'').trim(),String(v.password||''))}catch(err){r=null}adminBusy=false;const ok=r===true||!!(r&&r.ok);if(!ok){adminErr=(r&&r.err)||'Those are not the admin’s sign-in details.';layout();return}state.planLock={locked:false,unlockedAt:new Date().toISOString()};persist();adminErr='';adminEmail='';modals=modals.filter(m=>m!=='admin');layout();info('Plan unlocked. You can now set it up again.');return}
 if(n==='plan'){if(v.start>=v.examDate){info('The target exam date must be later than the start date.');return}if(v.examDate>v.deadline){info('Target exam date must be on or before your deadline.');return}if(dayDiff(v.start,v.examDate)>729){info('Use a study period shorter than two years.');return}const p=getPlan();Object.assign(p,{start:v.start,examDate:v.examDate,deadline:v.deadline,title:v.title.slice(0,90),reviewDays:clamp(+v.reviewDays||10,3,40),weeklyMinutes:WD.map((_,i)=>clamp(+v['wd'+i]||0,0,600))});if(p.weeklyMinutes.every(x=>!x)){info('Set study time on at least one day per week.');return}ask('After locking you can’t change the plan type, dates, hours or topics. Only the admin can unlock it.',{title:`Save and lock the ${state.planMode==='normal'?'Normal':'Relaxed'} plan?`,ok:'Save & lock'},()=>{state.plans[state.planMode]=p;state.planLock={locked:true,mode:state.planMode,at:new Date().toISOString()};track(`Set up and locked the ${state.planMode==='normal'?'Normal':'Relaxed'} study plan`,'CISA · Study planner');weekIndex=0;persist();if(modals[modals.length-1]==='config'){closeModal();return}layout()});return}
 if(n==='topic'){const id=v.id;if(!v.title.trim()){info('Enter a topic title.');return}if(v.date&&(v.date<getPlan().start||v.date>getPlan().examDate)){info('Preferred date must be between the plan start and target exam date.');return}if(id==='new'){let newId='P'+Date.now().toString(36);state.customTasks.push({id:newId,title:v.title.trim(),domain:clamp(+v.domain,1,5),section:'Personal study',minutes:clamp(+v.minutes,15,300),custom:true});state.topicEdits[newId]={date:v.date||'',notes:v.notes||'',title:v.title.trim(),minutes:clamp(+v.minutes,15,300)};}else{state.topicEdits[id]={title:v.title.trim(),minutes:clamp(+v.minutes,15,300),date:v.date||'',notes:v.notes||''};if(state.customTasks.some(x=>x.id===id)){state.customTasks.find(x=>x.id===id).domain=clamp(+v.domain,1,5)}}editTopic=null;persist();layout();return}
 if(n==='log'){if(+v.correct>+v.questions){info('Correct answers cannot exceed questions attempted.');return}if(!v.date||!+v.minutes){info('Date and study duration are required.');return}state.logs.push({id:'log'+Date.now(),date:v.date,domain:+v.domain,topicId:v.topicId||'',minutes:clamp(+v.minutes,1,1440),questions:clamp(+v.questions||0,0,1000),correct:clamp(+v.correct||0,0,1000),confidence:+v.confidence,notes:(v.notes||'').slice(0,1000)});state.logs=state.logs.slice(-200);stopwatchStart=null;stopwatchElapsed=0;clearInterval(stopWatch);persist();track(`Logged a study session: ${clamp(+v.minutes,1,1440)} min · Domain ${v.domain}${v.topicId?' · '+topicName(v.topicId):''}${+v.questions?` · ${+v.correct}/${+v.questions} questions`:''} (for ${v.date})`,'CISA · Daily recorder');layout();return}
 if(n==='notes'){state.notes[v.id]=(v.note||'').slice(0,2500);focusedTopic=v.id;persist();layout();return}
 if(n==='import'){const file=f.elements.backup.files?.[0];if(!file)return;if(file.size>2_000_000){info('Backup is too large (maximum 2 MB).');return}try{const obj=JSON.parse(await file.text());if(obj.kind!=='jslearning-cisa-v1'||!obj.data||typeof obj.data!=='object')throw Error('Not a JS Learning CISA backup');ask('Your current CISA progress on this account will be replaced.',{title:'Restore this backup?',ok:'Replace',danger:true},()=>{state=Object.assign(defaultState(),obj.data);ensureImported();persist();layout()})}catch(err){info('Unable to import: '+err.message)}return}
}
function ensureImported(){state.plans=state.plans||{};state.complete=state.complete||{};state.topicEdits=state.topicEdits||{};state.customTasks=Array.isArray(state.customTasks)?state.customTasks:[];state.logs=Array.isArray(state.logs)?state.logs:[];state.results=Array.isArray(state.results)?state.results:[];state.order=Array.isArray(state.order)?state.order:[];state.hidden=Array.isArray(state.hidden)?state.hidden:[];state.notes=state.notes||{};state.revisions=state.revisions||{};state.drafts=state.drafts||{};state.registration=state.registration||{registered:false,booked:false};state.revisionCounts=state.revisionCounts||{};state.mistakes=(state.mistakes&&typeof state.mistakes==='object')?state.mistakes:{};state.mockAttempts=state.mockAttempts||{};normaliseAttempts();if(!state.plans.normal)state.plans.normal=structuredClone(templates.normal);if(!state.plans.relaxed)state.plans.relaxed=structuredClone(templates.relaxed);if(!['normal','relaxed'].includes(state.planMode))state.planMode='normal';if(state.planLock&&state.planLock.locked&&['normal','relaxed'].includes(state.planLock.mode))state.planMode=state.planLock.mode}
function fail(message){if(root)root.innerHTML=`<div class="cisa-hub"><div class="cisa-error"><b>Unable to load the CISA module.</b><p>${h(message)}</p><p>Upload <code>cisa/</code> as a folder alongside <code>index.html</code>, including its JS, CSS and JSON files.</p></div></div>`}
export async function mount({root:target,read,write,isAdmin=false,verifyAdmin=null,readLearners=null,unlockLearner=null,track:trackFn=null,tab:startTab=null,topic:startTopic=null,section:startSection=null}){ensureManGuide();if(startSection){const pr=startSection.split('.');manSec=pr.slice(0,2).join('.');manOpenSub=pr.length>2?startSection:null;manView='guide';if(manOpenSub)setTimeout(()=>document.getElementById('sub-'+manOpenSub.replace(/\./g,'-'))?.scrollIntoView({block:'center'}),700)}ctx={isAdmin:!!isAdmin,verifyAdmin,readLearners,unlockLearner,track:trackFn};root=target;if(startTopic)focusedTopic=startTopic;if(startTab&&['learners','overview','planner','manual','syllabus','recorder','revision','mocks','mistakes','analytics','notes'].includes(startTab)){tab=startTab;mxSession=null;qzSession=null;modals=[]}readParent=read;writeParent=write;root.innerHTML='<div class="cisa-hub"><div class="cisa-card">Loading CISA Academy, planner and syllabus…</div></div>';try{if(!syllabus){[syllabus,templates.normal,templates.relaxed]=await Promise.all([fetchData('./data/syllabus.json'),fetchData('./data/normal-plan.json'),fetchData('./data/relaxed-plan.json')])}ensureState();weekIndex=clamp(Math.floor(dayDiff(getPlan().start,dateStr(new Date()))/7),0,99);root.onclick=action;root.onchange=changes;root.onsubmit=submit;layout()}catch(e){console.error(e);fail(e.message)}}
